import pytest
from target import solution


def test_example_1():
    assert solution([5, 8, 7, 1]) == 12


def test_example_2():
    assert solution([3, 3, 3, 3, 3]) == 9


def test_example_3():
    assert solution([30, 13, 24, 321]) == 0


def test_single_element_odd():
    # position 0 is even, element is odd -> included
    assert solution([7]) == 7


def test_single_element_even():
    # position 0 is even, element is even -> not included
    assert solution([4]) == 0


def test_two_elements_only_first_counted():
    # position 1 (odd index) should be excluded even if odd
    assert solution([3, 5]) == 3


def test_two_elements_first_even():
    assert solution([4, 5]) == 0


def test_negative_odd_numbers_at_even_positions():
    # positions 0,2 -> -3, -5 both odd -> sum = -8
    assert solution([-3, 2, -5, 4]) == -8


def test_negative_even_numbers_at_even_positions():
    assert solution([-4, 3, -6, 5]) == 0


def test_all_even_positions_even_values():
    assert solution([2, 1, 4, 3, 6, 5]) == 0


def test_all_even_positions_odd_values():
    assert solution([1, 2, 3, 4, 5, 6]) == 9


def test_zero_at_even_position_not_odd():
    # zero is even, should not be counted
    assert solution([0, 1, 0, 1]) == 0


def test_mixed_signs_and_values():
    # positions: 0=-1(odd),1=10,2=7(odd),3=-8,4=0,5=3
    assert solution([-1, 10, 7, -8, 0, 3]) == 6

from target import simplify


def test_example_1():
    assert simplify("1/5", "5/1") is True


def test_example_2():
    assert simplify("1/6", "2/1") is False


def test_example_3():
    assert simplify("7/10", "10/2") is False


def test_simple_whole_number():
    assert simplify("1/2", "2/1") is True


def test_simple_non_whole_number():
    assert simplify("1/3", "2/1") is False


def test_identity_one_over_one():
    assert simplify("1/1", "1/1") is True


def test_large_numbers_whole():
    assert simplify("3/7", "14/3") is True


def test_large_numbers_non_whole():
    assert simplify("3/7", "14/5") is False


def test_numerator_equals_denominator_other():
    assert simplify("5/5", "3/3") is True


def test_both_fractions_reduce_to_whole():
    assert simplify("4/6", "3/2") is True


def test_result_less_than_one():
    assert simplify("1/10", "1/1") is False


def test_result_exactly_one():
    assert simplify("2/3", "3/2") is True


def test_numerator_one_denominator_large():
    assert simplify("1/100", "100/1") is True


def test_denominator_does_not_cancel():
    assert simplify("1/100", "99/1") is False


def test_both_numerators_one():
    assert simplify("1/4", "1/4") is False


def test_cross_reduction_needed():
    assert simplify("2/4", "4/2") is True


def test_return_type_is_bool_true():
    result = simplify("1/5", "5/1")
    assert isinstance(result, bool)


def test_return_type_is_bool_false():
    result = simplify("1/6", "2/1") 
    assert isinstance(result, bool)
